    getButtons: function(cfg) {
        if(!this._buttons) {
            this._buttons = [];
            if(cfg.action == 'create' && !cfg.disableSaveAndNew)
                this._buttons.push({
                    text: 'Salvar e novo',
                    scope: this,
                    handler: function() { this.save_tag(cfg); }
                });
            if(!cfg.disableSave)
                this._buttons.push({
                    text: 'Salvar',
                    scope: this,
                    handler: function() { this.save_tag(cfg); }
                });
            this._buttons.push(
                {
                    text: 'Fechar',
                    scope: this,
                    handler: this.destroy
                }
            );

        }

        return this._buttons;
    },

   
    save_tag: function(cfg){
        var params = this.getFormPanel().getForm().getValues()
        params['pk'] = cfg.action == "update"?cfg.values.pk:undefined
        var rest = this.factoryRestful();
        var mask = new Ext.LoadMask(this.getEl(), {msg: 'Persistindo dados...'});
        mask.show();
        rest.doRequest(
            rest.getRoute('save', false, 'POST', {
                scope: this,
                params,
                callback: function() {
                    mask.hide();
                    mask = undefined;
                },
                success: function(xhr) {
                    var rst = Ext.decode(xhr.responseText);

                    if(rst.success) {
                        this.ownerGrid.getStore().reload()
                        this.destroy();
                    }
                    else
                        Ext.Msg.show({
                            title: 'Atenção',
                            icon: Ext.Msg.ERROR,
                            buttons: Ext.Msg.OK,
                            msg: rst.message
                        });
                },
                failure: function(xhr) {
                    Ext.Msg.show({
                        title: 'Atenção',
                        icon: Ext.Msg.ERROR,
                        buttons: Ext.Msg.OK,
                        msg: 'Recurso indisponível no momento.'
                    });
                },
            })
        );
    },
    
